import React from 'react';

function HeroSection({ currentMovie }) {
  const title = currentMovie?.title || "MY PROJECT X";
  const backdrop = currentMovie?.backdrop_path 
    ? `https://image.tmdb.org/t/p/original${currentMovie.backdrop_path}` 
    : 'https://images.unsplash.com/photo-1536440136628-849c177e76a1?auto=format&fit=crop&q=80&w=1200';

  return (
    <div className="relative w-full h-[520px] bg-[#0b090e] flex flex-col justify-between p-6 md:p-10 overflow-hidden">
      {/* 배경 이미지 및 그라데이션 */}
      <div className="absolute inset-0 opacity-40 bg-cover bg-center transition-all duration-700" style={{ backgroundImage: `url('${backdrop}')` }} />
      <div className="absolute inset-0 bg-gradient-to-t from-[#0b090e] via-black/40 to-black/60 z-10" />
      
      {/* 상단 네비게이션 영역 (뒤로가기 & 티켓 위젯) */}
      <div className="relative z-20 flex justify-between items-center w-full max-w-6xl mx-auto">
        <button className="w-10 h-10 rounded-full bg-white/10 backdrop-blur-md text-white flex items-center justify-center hover:bg-white/20 transition cursor-pointer border border-white/10">
          &larr;
        </button>

        {/* 💡 이미지 참고: 우측 상단 티켓 스타일 위젯 */}
        <div className="flex items-center bg-white/90 backdrop-blur-md text-zinc-900 rounded-lg p-2 shadow-2xl border-2 border-dashed border-zinc-300">
          <div className="px-3 border-r border-zinc-300">
            <span className="text-[10px] text-zinc-500 block uppercase font-bold">Now Playing</span>
            <span className="text-xs font-black tracking-wider text-purple-900">{title}</span>
          </div>
          <div className="px-3 flex items-center gap-2">
            <span className="text-[10px] bg-purple-100 text-purple-700 px-1.5 py-0.5 rounded font-bold">2026</span>
            <span className="text-[10px] font-bold text-zinc-700">IMAX</span>
          </div>
        </div>
      </div>

      {/* 중앙 영화 타이틀 및 정보 */}
      <div className="relative z-20 max-w-4xl mx-auto w-full text-left mb-4">
        <span className="text-xs uppercase tracking-widest text-purple-400 font-extrabold">DOCUMENTARY / DRAMA</span>
        <h2 className="text-4xl md:text-6xl font-black text-white mt-1 mb-3 tracking-wide drop-shadow-lg">{title}</h2>
        <div className="flex items-center gap-6 text-xs text-zinc-300">
          <span>DIRECTOR : <strong className="text-white">LIMOR PINHASOV</strong></span>
          <span>YEAR : <strong className="text-white">2026</strong></span>
          <span>CATEGORY : <strong className="text-white">CINEMA</strong></span>
        </div>
      </div>

    </div>
  );
}

export default HeroSection;
